#include <cstddef>
#include <vector>

class Matrix
{
public:
    Matrix(std::size_t rows, std::size_t columns)
        : m_rows{ rows }, m_columns{ columns }, m_data(rows * columns, 0.0)
    {
    }

    static Matrix identity(std::size_t n)
    {
        Matrix m{ n, n };
        for (std::size_t i{ 0 }; i < n; ++i)
        {
            m(i, i) = 1.0;
        }
        return m;
    }

    std::size_t rows() const { return m_rows; }
    std::size_t columns() const { return m_columns; }

    double& operator()(std::size_t row, std::size_t column) { return m_data[row * m_columns + column]; }
    const double& operator()(std::size_t row, std::size_t column) const { return m_data[row * m_columns + column]; }

    friend bool operator==(const Matrix& a, const Matrix& b)
    {
        return a.m_rows == b.m_rows && a.m_columns == b.m_columns && a.m_data == b.m_data;
    }

private:
    std::size_t m_rows{};
    std::size_t m_columns{};
    std::vector<double> m_data{};
};

Matrix operator+(const Matrix& a, const Matrix& b)
{
    Matrix result{ a.rows(), a.columns() };
    for (std::size_t r{ 0 }; r < a.rows(); ++r)
    {
        for (std::size_t c{ 0 }; c < a.columns(); ++c)
        {
            result(r, c) = a(r, c) + b(r, c);
        }
    }
    return result;
}

Matrix operator*(const Matrix& a, const Matrix& b)
{
    Matrix result{ a.rows(), b.columns() };
    for (std::size_t r{ 0 }; r < a.rows(); ++r)
    {
        for (std::size_t c{ 0 }; c < b.columns(); ++c)
        {
            double sum{ 0.0 };
            for (std::size_t k{ 0 }; k < a.columns(); ++k)
            {
                sum += a(r, k) * b(k, c);
            }
            result(r, c) = sum;
        }
    }
    return result;
}

