Matrix make(std::size_t rows, std::size_t cols, std::initializer_list<double> values) { Matrix m{ rows, cols }; std::size_t i{ 0 }; for (double v : values) { m(i / cols, i % cols) = v; ++i; } return m; }

TEST("starts as zeros with the right shape") { const Matrix m{ 2, 3 }; CHECK_EQ(m.rows(), 2u); CHECK_EQ(m.columns(), 3u); CHECK_NEAR(m(1, 2), 0.0, 1e-12); }
TEST("read and write with ()") { Matrix m{ 2, 2 }; m(0, 1) = 5.5; m(1, 0) = -2; CHECK_NEAR(m(0, 1), 5.5, 1e-12); CHECK_NEAR(m(1, 0), -2.0, 1e-12); CHECK_NEAR(m(0, 0), 0.0, 1e-12); }
TEST("equality") { CHECK(make(2, 2, { 1, 2, 3, 4 }) == make(2, 2, { 1, 2, 3, 4 })); CHECK(!(make(2, 2, { 1, 2, 3, 4 }) == make(2, 2, { 1, 2, 3, 5 }))); CHECK(!(Matrix{ 2, 3 } == Matrix{ 3, 2 })); }
TEST("addition") { CHECK(make(2, 2, { 1, 2, 3, 4 }) + make(2, 2, { 10, 20, 30, 40 }) == make(2, 2, { 11, 22, 33, 44 })); }
TEST("multiplication") { CHECK(make(2, 3, { 1, 2, 3, 4, 5, 6 }) * make(3, 2, { 7, 8, 9, 10, 11, 12 }) == make(2, 2, { 58, 64, 139, 154 })); }
TEST("identity") { const Matrix a{ make(2, 2, { 1, 2, 3, 4 }) }; CHECK(a * Matrix::identity(2) == a); CHECK(Matrix::identity(3) == make(3, 3, { 1, 0, 0, 0, 1, 0, 0, 0, 1 })); }

